\label{thm:known-quadrilaterals}
	Let $U\in\mathcal{U}(2,4)$ and $\gamma\in C_{{\tt cv}}(U)$. Then
	\begin{enumerate}
		\item $S(U,\gamma)$ is finite if and only if $U$ is irreducible;
		\item if $U$ is irreducible, then
		$
		|S(U,\gamma)|\in\{1,2,3\}$.
	\end{enumerate}

\label{conj:irreduc}
	Let $U\in\mathcal{U}(n,m)$ and $\gamma\in C_{{\tt cv}}(U)$. Then 
	$S(U,\gamma)$ is finite if and only if $U$ is irreducible.

\label{thm:parity}
	Let $U\in\mathcal{U}(n,m)$ be in general position and 
	$\gamma\in C_{{\tt cv}}(U)\setminus B(U)$. Then $|S(U,\gamma)|$ is odd.

\label{prop:irreducible-regular-point}
	Let $U\in\mathcal{U}(n,m)$. Then
	$U$ is irreducible if and only if $W(U)\neq\varnothing$.

Let
$E=\{h\in\mathbb{R}^m:\operatorname*{int} P(U,h)\neq\varnothing\}$ and
$v(h)=\operatorname{vol}(P(U,h))$ for $h\in E$. We write
$\Lambda=\{U^\intercal t:t\in\mathbb{R}^n\}$; as $U$ spans $\mathbb{R}^n$, the map
$t\mapsto U^\intercal t$ is injective. Since
$P(U,h-U^\intercal t)=P(U,h)-t$, we have $E=\mathbb{R}^m_{>0}+\Lambda$ and
\begin{equation}
	\label{eq:parity-transl}
	v(h-U^\intercal t)=v(h),\qquad h\in E,\ t\in\mathbb{R}^n.
\end{equation}
It is classical that $v$ is continuously differentiable on $E$ with
\begin{equation}
	\label{eq:parity-dv}
	\frac{\partial v}{\partial h_i}(h)=\operatorname{vol}_{n-1}(F_i(h)),
	\qquad 1\leq i\leq m,
\end{equation}
see \cite[Section~5.1]{Schneider2014}: on every type-cone this follows
from Lemma~\ref{res:type_cones_and_volume_polynomials} and
\eqref{eq:facetineq}, and the right hand sides of \eqref{eq:parity-dv}
are continuous. Consequently,
\begin{equation}
	\label{eq:parity-fcvdv}
	f_{{\tt cv}}^U(b)_i=\frac{b_i}{n}\frac{\partial v}{\partial b_i}(b),
	\qquad b\in\mathbb{R}^m_{>0}.
\end{equation}
Both $v$ and $f_{{\tt cv}}^U$ are positively homogeneous of degree $n$. Hence
$S(U,\tau^n\gamma)=\tau S(U,\gamma)$ for $\tau>0$, the sets $W(U)$ and
$B(U)$ are invariant under such scalings, and
$\det Df_{{\tt cv}}^U(\tau b)=\tau^{m(n-1)}\det Df_{{\tt cv}}^U(b)$. Therefore it
suffices to prove Theorem~\ref{thm:parity2} for $\gamma$ with
$\|\gamma\|_1=1$, which we assume from now on.
